from dataclasses import dataclass
import re
import datetime

@dataclass
class Record:
    id: int
    content: str
    timestamp: datetime.datetime

def is_old_record(record):
    return (datetime.datetime.now() - record.timestamp).days > 30

def sanitize_html(content):
    return re.sub(r'<.*?>', '', content)

def archive_old_records(records):
    archived = []
    for record in records:
        if is_old_record(record):
            sanitized_content = sanitize_html(record.content)
            archived.append((record.id, sanitized_content))
    return archived

