import hmac

class HTMLSanitizer:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def sanitize(self, html):
        tag_re = re.compile(r'<[^>]+>')
        return tag_re.sub('', html)

    def verify_signature(self, data, signature):
        expected_signature = hmac.new(self.secret_key.encode(), data.encode(), 'sha256').hexdigest()
        return hmac.compare_digest(expected_signature, signature)

    def sanitize_comments(self, comments):
        return {user: self.sanitize(comment) for user, comment in comments.items()}

